-- Use current complete imports and existing responsibility fallback; no source data changes.
-- Isolated calendar analytics; existing business calculations remain unchanged.
create or replace function public.crm_meeting_source_metrics_v2(p_source text,p_month date,p_manager text default null)
returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp set statement_timeout='8s' as $$
declare result jsonb;
begin
 if p_month is null or p_month<>date_trunc('month',p_month)::date then raise exception 'invalid_month'; end if;
 case p_source
 when 'clients' then
 select jsonb_build_object('source','clients','period_mode','current_state','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where nullif(trim(address),'') is null or (manager_id is null and nullif(trim(manager_name),'') is null)))) into result from public.clients where (p_manager is null or manager_name=p_manager) and is_archived is not true and to_delete is not true;
 when 'motivation' then
 select jsonb_build_object('source','manager_kpi_plans','check_label', 'Планы с незаполненным или неположительным планом отгрузок/АКБ','period_mode','selected_month','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where shipment_plan is null or shipment_plan<=0 or akb_plan is null or akb_plan<=0),'shipment_plan',coalesce(sum(shipment_plan),0),'akb_plan',coalesce(sum(akb_plan),0),'new_clients_plan',coalesce(sum(new_clients_plan),0))) into result from public.manager_kpi_plans where (p_manager is null or manager_name=p_manager) and period_month=p_month::text;
 when 'visits' then
 select jsonb_build_object('source','visits','check_label', 'Визиты без заполненного результата','period_mode','selected_month','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where nullif(trim(result),'') is null))) into result from public.visits where is_duplicate is not true and (p_manager is null or manager_name=p_manager) and date>=p_month and date<(p_month+interval '1 month');
 when 'routes' then
 select jsonb_build_object('source','route_plans','period_mode','selected_month','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where visited is not true and approved is true and review_status='approved' and visit_date < (now() at time zone 'Europe/Minsk')::date))) into result from public.route_plans where removed is not true and (p_manager is null or manager_name=p_manager) and visit_date>=p_month and visit_date<(p_month+interval '1 month');
 when 'tasks' then
 select jsonb_build_object('source','tasks','period_mode','current_state','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where due_date < (now() at time zone 'Europe/Minsk')::date and review_status='approved'),'approved_open',count(*) filter(where review_status='approved'),'stale_open',count(*) filter(where review_status='stale_review'),'stale_overdue',count(*) filter(where review_status='stale_review' and due_date < (now() at time zone 'Europe/Minsk')::date))) into result from public.tasks where done is not true and (p_manager is null or manager_name=p_manager);
 when 'debt' then
 select jsonb_build_object('source','client_debt','period_mode','latest_report_in_or_before_month','report_date',max(report_date),'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where debt_overdue>0),'debt_overdue',coalesce(sum(debt_overdue),0))) into result from public.client_debt where (p_manager is null or manager_name=p_manager) and report_date=(select max(report_date) from public.client_debt where report_date<(p_month+interval '1 month'));
 when 'gps' then
 select jsonb_build_object('source','gps_workday_aggregates','period_mode','selected_month','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where aggregation_status='stale'),'planned_count',coalesce(sum(planned_count),0),'visited_count',coalesce(sum(visited_count),0),'missed_count',coalesce(sum(missed_count),0),'distance_m',coalesce(sum(distance_m),0))) into result from public.gps_workday_aggregates where (p_manager is null or manager_name=p_manager) and work_date>=p_month and work_date<(p_month+interval '1 month');
 when 'imports' then
 select jsonb_build_object('source','crm_import_status','check_label', 'Источники с ошибкой либо без успешной загрузки за два дня','period_mode','current_state','report_date',max(last_success_at),'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where status is distinct from 'ok' or last_success_at is null or last_success_at<now()-interval '2 days'))) into result from public.crm_import_status;
 when 'stock' then
 select jsonb_build_object('source','stock_balances','check_label', 'Позиции с отрицательным доступным остатком','period_mode','latest_report_in_or_before_month','report_date',max(report_date),'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where qty_avail<0),'qty_onhand',coalesce(sum(qty_onhand),0),'qty_reserve',coalesce(sum(qty_reserve),0),'qty_avail',coalesce(sum(qty_avail),0))) into result from public.stock_balances where report_date=(select max(report_date) from public.stock_balances where report_date<(p_month+interval '1 month'));
 when 'stock_freshness' then
 select jsonb_build_object('source','warehouse_stock_import_state','check_label', 'Складские отчёты старше двух дней или без даты','period_mode','current_state','report_date',max(report_date),'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where report_date is null or report_date<(now() at time zone 'Europe/Minsk')::date-2))) into result from public.warehouse_stock_import_state;
 when 'markdown' then
 select jsonb_build_object('source','markdown_items','check_label', 'Товары уценки на этапе сбора данных','period_mode','current_state','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where quantity>0 and review_status='collecting'),'quantity',coalesce(sum(quantity),0))) into result from public.markdown_items where is_active=true;
 when 'stands' then
 select jsonb_build_object('source','stand_assets_v236346','check_label', 'Стенды с неподтверждённым исправным состоянием','period_mode','current_state','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where condition_status is distinct from 'ok'))) into result from public.stand_assets_v236346;
 when 'warehouse_orders' then
 select jsonb_build_object('source','warehouse_pick_orders_v1','check_label', 'Заказы комплектации со статусом ошибки или блокировки','period_mode','current_state','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where status in ('error','failed','blocked')),'line_count',coalesce(sum(line_count),0),'total_qty',coalesce(sum(total_qty),0))) into result from public.warehouse_pick_orders_v1;
 when 'warehouse_receiving' then
 select jsonb_build_object('source','warehouse_receiving_sessions','check_label', 'Приёмки со статусом ошибки или блокировки','period_mode','current_state','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where status in ('error','failed','blocked')),'expected_sku_count',coalesce(sum(expected_sku_count),0),'expected_qty',coalesce(sum(expected_qty),0))) into result from public.warehouse_receiving_sessions;
 when 'warehouse_inventory' then
 select jsonb_build_object('source','warehouse_inventory_sessions','check_label', 'Инвентаризации со статусом ошибки или блокировки','period_mode','current_state','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where status in ('error','failed','blocked')),'stock_sku_count',coalesce(sum(stock_sku_count),0))) into result from public.warehouse_inventory_sessions;
 when 'competitors' then
 select jsonb_build_object('source','triovist_competitor_analysis_current','check_label', 'Позиции, где наша цена выше найденной цены конкурента','period_mode','current_state','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where competitor_price>0 and our_price>competitor_price))) into result from public.triovist_competitor_analysis_current;
 when 'cards_21vek' then
 select jsonb_build_object('source','triovist_content_cards','period_mode','current_state','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where unanswered_questions>0 or unanswered_negative_reviews>0),'unanswered_questions',coalesce(sum(unanswered_questions),0),'negative_reviews',coalesce(sum(negative_reviews),0))) into result from public.triovist_content_cards where (p_manager is null or manager_name=p_manager) and import_id in (select id from public.triovist_content_imports where is_current and status='complete');
 when 'card_issues' then
 select jsonb_build_object('source','triovist_content_issues','check_label', 'Открытые критические проблемы карточек, присутствующих в последнем импорте','period_mode','current_state','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where severity='critical' and status='open' and missing_from_latest is not true))) into result from public.triovist_content_issues where (p_manager is null or manager_name=p_manager) and status not in ('resolved','dismissed');
 when 'triovist_stock' then
 select jsonb_build_object('source','triovist_partner_stock','period_mode','latest_report_in_or_before_month','report_date',max(snapshot_date),'metrics',jsonb_build_object('rows',count(*),'risk_count',null::bigint,'qty_free',coalesce(sum(qty_free),0),'qty_orders',coalesce(sum(qty_orders),0))) into result from public.triovist_partner_stock where snapshot_date=(select max(snapshot_date) from public.triovist_partner_stock where snapshot_date<(p_month+interval '1 month'));
 when 'triovist_tasks' then
 select jsonb_build_object('source','triovist_ai_tasks','period_mode','current_state','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where due_date < (now() at time zone 'Europe/Minsk')::date and status in ('new','in_progress','partial')))) into result from public.triovist_ai_tasks where (p_manager is null or manager_name=p_manager);
 when 'vip_actions' then
 select jsonb_build_object('source','vip_action_recommendations','check_label', 'Активные рекомендации VIP с положительной потерей выручки','period_mode','current_state','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where loss_revenue>0),'loss_revenue',coalesce(sum(loss_revenue),0))) into result from public.vip_action_recommendations where is_active=true;
 when 'cash' then
 select jsonb_build_object('source','cash_receipts_1c','check_label', 'Денежные документы с отрицательной суммой: сверка возвратов и корректировок','period_mode','selected_month','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where amount<0),'amount',coalesce(sum(amount),0))) into result from public.cash_receipts_1c where (p_manager is null or manager_name=p_manager) and document_at>=(p_month::timestamp at time zone 'Europe/Minsk') and document_at<((p_month+interval '1 month') at time zone 'Europe/Minsk');
 when 'promotion_budgets' then
 select jsonb_build_object('source','promotion_budgets','check_label', 'Бюджеты с отрицательной общей суммой','period_mode','selected_month','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where budget_total<0),'budget_total',coalesce(sum(budget_total),0))) into result from public.promotion_budgets where (p_manager is null or manager_name=p_manager) and period_start<(p_month+interval '1 month') and period_end>=p_month;
 when 'mrc' then
 select jsonb_build_object('source','triovist_mrc_current','check_label', 'Позиции МРЦ без положительной цены','period_mode','current_state','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where mrc_byn is null or mrc_byn<=0))) into result from public.triovist_mrc_current;
 when 'infographics' then
 select jsonb_build_object('source','triovist_infographic_factory_batches_v5','period_mode','selected_month','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'risk_count',coalesce(sum(failed_items),0),'total_items',coalesce(sum(total_items),0),'completed_items',coalesce(sum(completed_items),0),'failed_items',coalesce(sum(failed_items),0),'attention_items',coalesce(sum(attention_items),0))) into result from public.triovist_infographic_factory_batches_v5 where created_at>=p_month and created_at<(p_month+interval '1 month');
 when 'parser' then
 select jsonb_build_object('source','triovist_market_position_watch_runs_v236352','period_mode','selected_month','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'risk_count',count(*) filter(where error_count>0),'tracked_count',coalesce(sum(tracked_count),0),'success_count',coalesce(sum(success_count),0),'error_count',coalesce(sum(error_count),0))) into result from public.triovist_market_position_watch_runs_v236352 where started_at>=p_month and started_at<(p_month+interval '1 month');
 when 'lpr' then
 select jsonb_build_object('source','crm_lpr_contacts_v1','period_mode','current_state','report_date',null::text,'metrics',jsonb_build_object('rows',count(*),'missing_birthday',count(*) filter(where birth_month is null or birth_day is null),'missing_responsible',count(*) filter(where responsible_user_id is null and not exists(select 1 from public.clients c where c.id=l.client_id and nullif(trim(c.manager_name),'') is not null)),'risk_count',count(*) filter(where birth_month is null or birth_day is null or (responsible_user_id is null and not exists(select 1 from public.clients c where c.id=l.client_id and nullif(trim(c.manager_name),'') is not null))))) into result
 from public.crm_lpr_contacts_v1 l where l.active and (p_manager is null or exists(select 1 from public.users u where u.id=l.responsible_user_id and u.name=p_manager) or exists(select 1 from public.clients c where c.id=l.client_id and c.manager_name=p_manager));
 else raise exception 'unsupported_source';
 end case;
 return result;
end $$;
revoke all on function public.crm_meeting_source_metrics_v2(text,date,text) from public,anon,authenticated;
grant execute on function public.crm_meeting_source_metrics_v2(text,date,text) to service_role;

